	async function withEnterpriseFallback(params) {
		const explicit = typeof params?.enterpriseId === "string" ? params.enterpriseId.trim() : "";
		if (explicit) return {
			...params ?? {},
			enterpriseId: explicit
		};
		const eid = await resolveEnterpriseId();
		if (!eid) return params;
		return {
			...params ?? {},
			enterpriseId: eid
		};
	}
