/**
* CloudStudio Deploy RPC handlers.
*
* Desktop-only channels for UI-triggered deploy/destroy operations.
* Uses direct server.handle() (not handleRpc) since these channels
* are not in the shared workbuddy channel map.
*/
function registerCloudStudioDeployHandlers(server, deps) {
	const { cloudStudioDeployService } = deps;
	server.handle("cloudstudio:deploy", async (args) => {
		return await cloudStudioDeployService.deploy({
			localDir: args.directory,
			port: args.port,
			workspaceRoot: args.cwd,
			entryHtml: args.entryHtml,
			taskSessionId: args.taskSessionId,
			triggerType: args.triggerType
		});
	});
	server.handle("cloudstudio:deployTo", async (args) => {
		return await cloudStudioDeployService.deployTo(args.spaceKey, {
			localDir: args.directory,
			port: args.port,
			workspaceRoot: args.cwd
		});
	});
	server.handle("cloudstudio:destroy", async (args) => {
		if (args.conversationId) await cloudStudioDeployService.cancelArtifactRelease(args.conversationId);
		else if (args.spaceKey) await cloudStudioDeployService.destroy(args.spaceKey);
		else throw new Error("conversationId or spaceKey is required");
		return { success: true };
	});
	server.handle("cloudstudio:createWorkspace", async () => {
		return await cloudStudioDeployService.createWorkspace();
	});
	server.handle("cloudstudio:getDeployHistory", async (args) => cloudStudioDeployService.getDeployHistory(args?.workspaceRoot, args?.taskSessionIds));
	server.handle("cloudstudio:queryShareLink", async (args) => {
		const rawPath = path.resolve(args.filePath);
		if (!fs.existsSync(rawPath)) return { shareLink: null };
		const isFile = fs.statSync(rawPath).isFile();
		const dirPath = isFile ? path.dirname(rawPath) : rawPath;
		return { shareLink: findLatestDeployRecord(dirPath, isFile ? path.basename(rawPath) : detectEntryHtml(dirPath))?.shareLink || null };
	});
}
