//#region src/main/handlers/channel.ts
/**
* Push a channel event to the renderer via the unified 'channel:event' push channel.
* WorkbuddyChannel listens on 'channel:event' and dispatches to local event handlers.
*/
function pushChannelEvent(server, event, data) {
	server.push("channel:event", {
		event,
		data
	});
}
function registerChannelHandlers(server, deps) {
	server.handle("channel:callMethod", async () => ({ data: null }));
	server.handle("channel:sendNotification", async () => true);
	server.handle("channel:bindSession", async () => {});
	server.handle("channel:unbindSession", async () => {});
	server.handle("channel:emit", async (...args) => {
		const event = args[0];
		const data = args[1];
		if (event) pushChannelEvent(server, event, data);
	});
	registerClawHandlers(server, deps);
}
