function createCreditPredictionFacade(deps) {
	/** requestId → AbortController, 用于 cancel(requestId) 中断未完成请求。 */
	const inflight = /* @__PURE__ */ new Map();
	return {
		predict: async (request) => predictCreditUsage(deps, request, inflight),
		cancel: async (requestId) => {
			const controller = inflight.get(requestId);
			if (!controller) return { success: false };
			try {
				controller.abort();
			} catch {}
			inflight.delete(requestId);
			return { success: true };
		}
	};
}
async function predictCreditUsage(deps, request, inflight) {
	const { requestId, params, headers } = request;
	const session = deps.authenticationManager.currentSessionSubject.getValue();
	if (!session?.auth?.accessToken) return {
		success: false,
		error: "Not logged in"
	};
	const rawEndpoint = require_workbuddy_product_config.resolveEndpointOverride() ?? deps.productManager.getEndpoint();
	if (!rawEndpoint) return {
		success: false,
		error: "No endpoint"
	};
	const endpoint = rawEndpoint.replace(/\/+$/, "");
	const requestHeaders = {
		Accept: "application/json",
		Authorization: `Bearer ${session.auth.accessToken}`,
		"Content-Type": "application/json"
	};
	if (session.account?.uid) requestHeaders["X-User-Id"] = session.account.uid;
	if (session.account?.enterpriseId) {
		requestHeaders["X-Enterprise-Id"] = session.account.enterpriseId;
		requestHeaders["X-Tenant-Id"] = session.account.enterpriseId;
	}
	if (session.auth.domain) requestHeaders["X-Domain"] = session.auth.domain;
	requestHeaders["X-Conversation-ID"] = headers.conversationId;
	requestHeaders["X-Conversation-Request-ID"] = headers.conversationRequestId;
	requestHeaders["X-Conversation-Message-ID"] = headers.conversationMessageId;
	const controller = new AbortController();
	inflight.set(requestId, controller);
	try {
		const response = await electron.net.fetch(`${endpoint}/v2/chat/prediction`, {
			method: "POST",
			headers: requestHeaders,
			body: JSON.stringify(params),
			signal: controller.signal
		});
		if (!response.ok) return {
			success: false,
			error: `HTTP ${response.status}`
		};
		const json = await response.json();
		if (!json || json.code !== 0) return {
			success: false,
			error: json?.message ?? `code=${json?.code}`
		};
		const range = parsePredictedTotalCreditRange(json.data?.predicted_total_credit);
		if (!range) return {
			success: false,
			error: "invalid predicted_total_credit"
		};
		return {
			success: true,
			predictedTotalCredit: range
		};
	} catch (error) {
		if (error?.name === "AbortError" || controller.signal.aborted) return {
			success: false,
			cancelled: true
		};
		return {
			success: false,
			error: error instanceof Error ? error.message : String(error)
		};
	} finally {
		if (inflight.get(requestId) === controller) inflight.delete(requestId);
	}
}
/**
* 校验并归一化后端返回的 `predicted_total_credit` 区间。
*
* 接口契约：`{ min: number, max: number }`，min/max 必须是非负有限数；
* 容错：若 min > max（理论上不应发生），认为无效。
*/
function parsePredictedTotalCreditRange(value) {
	if (!value || typeof value !== "object") return;
	const { min, max } = value;
	if (typeof min !== "number" || !Number.isFinite(min) || min < 0) return;
	if (typeof max !== "number" || !Number.isFinite(max) || max < 0) return;
	if (min > max) return;
	return {
		min,
		max
	};
}
